"""Web page files kept in Python so the app has no folders."""

CSS = ':root {\n  --bg: #f4f2ee;\n  --card: #ffffff;\n  --ink: #1c1b19;\n  --muted: #74706a;\n  --line: #e4e0d9;\n  --accent: #1f5c4d;\n  --accent-ink: #ffffff;\n  --accent-soft: #e3efe9;\n  --warn: #9a3412;\n  --warn-soft: #fdecdf;\n  --radius: 14px;\n  --shadow: 0 1px 2px rgba(28, 27, 25, .05), 0 8px 24px rgba(28, 27, 25, .06);\n}\n* { box-sizing: border-box; }\nhtml, body { margin: 0; }\nbody {\n  background: var(--bg); color: var(--ink);\n  font: 15px/1.5 -apple-system, BlinkMacSystemFont, "Segoe UI", Inter, Roboto, Helvetica, Arial, sans-serif;\n}\nh1 { font-size: 22px; margin: 0; letter-spacing: -.01em; }\nh2 { font-size: 16px; margin: 0; }\n.hidden { display: none !important; }\n.muted { color: var(--muted); }\n.link { color: var(--ink); text-decoration: none; opacity: .75; }\n.link:hover { opacity: 1; text-decoration: underline; }\n\n/* top bar */\n.topbar {\n  display: flex; align-items: center; justify-content: space-between;\n  padding: 14px 28px; background: var(--card); border-bottom: 1px solid var(--line);\n  position: sticky; top: 0; z-index: 5;\n}\n.brand { display: flex; align-items: baseline; gap: 8px; text-decoration: none; color: var(--ink); }\n.mark { font-weight: 800; letter-spacing: .06em; font-size: 18px; }\n.brand-sub { color: var(--muted); font-weight: 500; }\n.brand.big .mark { font-size: 30px; }\n.brand.big .brand-sub { font-size: 20px; }\n.top-right { display: flex; gap: 16px; align-items: center; }\n.pill {\n  font-size: 13px; padding: 5px 12px; border-radius: 999px; background: var(--bg);\n  border: 1px solid var(--line); color: var(--muted); text-decoration: none; white-space: nowrap;\n}\n.pill.ok { background: var(--accent-soft); color: var(--accent); border-color: transparent; }\n.pill.action { background: var(--accent); color: var(--accent-ink); border-color: transparent; cursor: pointer; }\n\nmain { max-width: 1180px; margin: 0 auto; padding: 28px; }\n\n/* cards & forms */\n.card { background: var(--card); border-radius: var(--radius); box-shadow: var(--shadow); padding: 24px; }\n.card-head { display: flex; justify-content: space-between; align-items: center; gap: 16px; margin-bottom: 18px; flex-wrap: wrap; }\n.tabs { display: flex; background: var(--bg); padding: 4px; border-radius: 10px; }\n.tab { border: 0; background: none; padding: 7px 14px; border-radius: 8px; cursor: pointer; color: var(--muted); font: inherit; }\n.tab.active { background: var(--card); color: var(--ink); box-shadow: 0 1px 2px rgba(0,0,0,.08); }\nlabel { display: block; font-size: 13px; font-weight: 600; margin: 14px 0 6px; }\nlabel.check { font-weight: 400; display: flex; gap: 8px; align-items: center; font-size: 14px; }\ninput[type=url], input[type=text], input[type=password], select {\n  width: 100%; padding: 11px 12px; border: 1px solid var(--line); border-radius: 10px;\n  font: inherit; background: #fff; color: var(--ink);\n}\ninput:focus, select:focus { outline: 2px solid var(--accent-soft); border-color: var(--accent); }\n.row { display: flex; gap: 14px; flex-wrap: wrap; }\n.row .grow { flex: 1 1 280px; }\n.actions { display: flex; align-items: center; gap: 14px; margin-top: 20px; }\n.msg { font-size: 14px; color: var(--muted); }\n.msg.err, .error { color: var(--warn); }\n\n.btn {\n  display: inline-flex; align-items: center; justify-content: center; gap: 6px;\n  border: 1px solid var(--line); background: var(--card); color: var(--ink);\n  padding: 10px 18px; border-radius: 10px; font: inherit; font-weight: 600; cursor: pointer; text-decoration: none;\n}\n.btn:hover { border-color: #cfc9bf; }\n.btn.primary { background: var(--accent); border-color: var(--accent); color: var(--accent-ink); }\n.btn.primary:hover { filter: brightness(1.08); }\n.btn.ghost { border-color: transparent; color: var(--muted); }\n.btn.small { padding: 4px 10px; font-size: 13px; }\n.btn.wide { width: 100%; margin-top: 18px; }\n.btn:disabled { opacity: .5; cursor: default; }\n\n.drop {\n  border: 2px dashed var(--line); border-radius: var(--radius); padding: 30px; text-align: center;\n  transition: background .15s, border-color .15s;\n}\n.drop.over { background: var(--accent-soft); border-color: var(--accent); }\n.drop p { margin: 4px 0; }\n\n.progress { height: 6px; background: var(--line); border-radius: 99px; overflow: hidden; margin-top: 14px; }\n.progress > div { height: 100%; width: 0; background: var(--accent); transition: width .4s; }\n\n/* jobs list */\n.section-title { margin: 34px 0 14px; color: var(--muted); font-weight: 600; text-transform: uppercase; font-size: 12px; letter-spacing: .08em; }\n.jobs { display: grid; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); gap: 18px; }\n.job-card {\n  background: var(--card); border-radius: var(--radius); box-shadow: var(--shadow); overflow: hidden;\n  text-decoration: none; color: var(--ink); display: flex; flex-direction: column; transition: transform .15s;\n}\n.job-card:hover { transform: translateY(-2px); }\n.job-card .thumb { aspect-ratio: 3 / 2; background: #e9e5de center / cover no-repeat; display: grid; place-items: center; color: var(--muted); font-size: 13px; }\n.job-card .info { padding: 14px 16px 16px; }\n.job-card h3 { font-size: 15px; margin: 0 0 4px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n.status { font-size: 13px; color: var(--muted); }\n.status.done { color: var(--accent); }\n.status.error { color: var(--warn); }\n\n/* job page */\n.job-head { display: flex; align-items: center; gap: 20px; flex-wrap: wrap; }\n.job-title { flex: 1; min-width: 240px; }\n.job-title p { margin: 2px 0 0; }\n.job-actions { display: flex; gap: 10px; }\n#job-dest { font-size: 13px; margin: 10px 0 0; }\n.notice { background: var(--warn-soft); color: var(--warn); padding: 12px 16px; border-radius: 10px; margin-top: 16px; font-size: 14px; }\n.gallery { display: grid; grid-template-columns: repeat(auto-fill, minmax(340px, 1fr)); gap: 20px; margin-top: 22px; }\n.photo { background: var(--card); border-radius: var(--radius); box-shadow: var(--shadow); overflow: hidden; }\n.photo .meta { display: flex; justify-content: space-between; align-items: center; padding: 10px 14px; font-size: 13px; }\n.photo .meta a { color: var(--accent); font-weight: 600; text-decoration: none; }\n\n/* before / after slider */\n.ba { position: relative; aspect-ratio: 3 / 2; overflow: hidden; cursor: ew-resize; user-select: none; background: #ddd; touch-action: pan-y; }\n.ba img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; pointer-events: none; }\n.ba .before { clip-path: inset(0 50% 0 0); }\n.ba .handle { position: absolute; top: 0; bottom: 0; left: 50%; width: 2px; background: #fff; box-shadow: 0 0 0 1px rgba(0,0,0,.15); }\n.ba .handle::after {\n  content: \'‹ ›\'; position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%);\n  background: #fff; color: var(--ink); border-radius: 99px; padding: 4px 9px; font-size: 13px; font-weight: 700;\n  box-shadow: 0 2px 8px rgba(0,0,0,.2); letter-spacing: 2px;\n}\n.ba .tag { position: absolute; top: 10px; font-size: 11px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: #fff; background: rgba(0,0,0,.45); padding: 3px 8px; border-radius: 6px; }\n.ba .tag.l { left: 10px; } .ba .tag.r { right: 10px; }\n.ba .zoom { position: absolute; bottom: 10px; right: 10px; background: rgba(255,255,255,.9); border: 0; border-radius: 8px; padding: 4px 9px; cursor: pointer; font: inherit; font-size: 12px; font-weight: 600; }\n\n.viewer { position: fixed; inset: 0; background: rgba(15, 15, 14, .92); z-index: 20; display: flex; flex-direction: column; align-items: center; justify-content: center; padding: 30px; }\n.big-ba { width: min(92vw, 150vh); }\n.viewer-close { position: absolute; top: 14px; right: 20px; background: none; border: 0; color: #fff; font-size: 36px; cursor: pointer; }\n.viewer-cap { color: #ddd; font-size: 14px; }\n\n/* login */\n.login-page { min-height: 100vh; display: grid; place-items: center; padding: 20px; }\n.login-card { background: var(--card); padding: 36px; border-radius: 18px; box-shadow: var(--shadow); width: min(380px, 100%); }\n.login-card p { margin: 6px 0 18px; }\n\n@media (max-width: 640px) {\n  main { padding: 18px; }\n  .topbar { padding: 12px 16px; }\n  .gallery { grid-template-columns: 1fr; }\n}\n'

JS = '(() => {\n  const $ = (s, el = document) => el.querySelector(s);\n  const $$ = (s, el = document) => [...el.querySelectorAll(s)];\n  const esc = s => String(s ?? \'\').replace(/[&<>"\']/g, c => ({ \'&\': \'&amp;\', \'<\': \'&lt;\', \'>\': \'&gt;\', \'"\': \'&quot;\', "\'": \'&#39;\' }[c]));\n  const api = async (url, opts = {}) => {\n    const r = await fetch(url, { headers: { \'Content-Type\': \'application/json\' }, ...opts });\n    if (r.status === 401) { location.href = \'/login\'; throw new Error(\'signed out\'); }\n    const j = await r.json().catch(() => ({}));\n    if (!r.ok) throw new Error(j.error || `Error ${r.status}`);\n    return j;\n  };\n  const ago = t => {\n    const s = Date.now() / 1000 - t;\n    if (s < 60) return \'just now\';\n    if (s < 3600) return `${Math.floor(s / 60)} min ago`;\n    if (s < 86400) return `${Math.floor(s / 3600)} h ago`;\n    return new Date(t * 1000).toLocaleDateString();\n  };\n  const pct = j => {\n    if (j.status === \'done\') return 100;\n    if (j.status === \'saving\' && j.photo_count) return 90 + 10 * (j.saved_count / j.photo_count);\n    if (j.sets_total) return 8 + 82 * (j.sets_done / j.sets_total);\n    return j.status === \'downloading\' ? 4 : 2;\n  };\n\n  // ------------------------------------------------------------ tabs\n  $$(\'.tab\').forEach(t => t.onclick = () => {\n    $$(\'.tab\').forEach(x => x.classList.toggle(\'active\', x === t));\n    $$(\'.tab-body\').forEach(b => b.classList.toggle(\'hidden\', b.dataset.body !== t.dataset.tab));\n  });\n\n  // ------------------------------------------------------------ status / jobs list\n  let status = null;\n  async function refresh() {\n    try { status = await api(\'/api/status\'); } catch { return; }\n    const pill = $(\'#dbx-pill\');\n    if (!status.dropbox_configured) {\n      pill.className = \'pill\'; pill.textContent = \'Dropbox not set up\'; pill.onclick = null;\n    } else if (status.dropbox_connected) {\n      if (pill.dataset.armed) { renderJobs(status.jobs); if (current) loadJob(current, true); return; }\n      pill.className = \'pill ok\'; pill.textContent = \'Dropbox connected\';\n      pill.title = status.dropbox_account + \' · click to disconnect\';\n      pill.onclick = async () => {\n        if (pill.dataset.armed) { await api(\'/api/dropbox/disconnect\', { method: \'POST\' }); delete pill.dataset.armed; refresh(); return; }\n        pill.dataset.armed = \'1\'; pill.textContent = \'Click again to disconnect\';\n        setTimeout(() => { delete pill.dataset.armed; refresh(); }, 4000);\n      };\n    } else {\n      pill.className = \'pill action\'; pill.textContent = \'Connect Dropbox\';\n      pill.onclick = () => { location.href = \'/dropbox/connect\'; };\n    }\n    renderJobs(status.jobs);\n    if (current) loadJob(current, true);\n  }\n\n  function renderJobs(jobs) {\n    const el = $(\'#jobs\');\n    if (!jobs.length) { el.innerHTML = \'<p class="muted">No edits yet. Paste a Dropbox link above to start.</p>\'; return; }\n    el.innerHTML = jobs.map(j => {\n      const thumb = j.cover ? `style="background-image:url(\'/jobs/${j.id}/after/${encodeURIComponent(j.cover)}.jpg\')"` : \'\';\n      const progress = [\'done\', \'error\'].includes(j.status) ? \'\' : `<div class="progress"><div style="width:${pct(j)}%"></div></div>`;\n      const line = j.status === \'done\' ? `${j.photo_count} photos` : (j.message || j.status_label);\n      return `<a class="job-card" href="#/job/${j.id}">\n        <div class="thumb" ${thumb}>${j.cover ? \'\' : esc(j.status_label)}</div>\n        <div class="info"><h3>${esc(j.name)}</h3>\n          <div class="status ${j.status}">${esc(line)} · ${ago(j.created)}</div>${progress}</div></a>`;\n    }).join(\'\');\n  }\n\n  // ------------------------------------------------------------ new edit: dropbox\n  $(\'#start-dbx\').onclick = async () => {\n    const msg = $(\'#dbx-msg\'); msg.className = \'msg\'; msg.textContent = \'Checking the link…\';\n    $(\'#start-dbx\').disabled = true;\n    try {\n      const j = await api(\'/api/jobs\', { method: \'POST\', body: JSON.stringify({\n        source: \'dropbox\', link: $(\'#link\').value, name: $(\'#name\').value,\n        per_set: +$(\'#per-set\').value, save_to_dropbox: $(\'#save-dbx\').checked }) });\n      msg.textContent = \'Started.\'; $(\'#link\').value = \'\'; $(\'#name\').value = \'\';\n      location.hash = `#/job/${j.id}`;\n    } catch (e) { msg.className = \'msg err\'; msg.textContent = e.message; }\n    $(\'#start-dbx\').disabled = false;\n  };\n\n  // ------------------------------------------------------------ new edit: upload\n  let picked = [];\n  const RAW = /\\.(rw2|cr2|cr3|nef|nrw|arw|srf|sr2|raf|orf|dng|pef|rwl|3fr|iiq|erf|mef|mos|srw|x3f)$/i;\n  const setFiles = list => {\n    picked = [...list].filter(f => RAW.test(f.name));\n    const gb = picked.reduce((a, f) => a + f.size, 0) / 1e9;\n    $(\'#up-msg\').className = \'msg\';\n    $(\'#up-msg\').textContent = picked.length ? `${picked.length} RAW files (${gb.toFixed(1)} GB)` : \'No RAW files in that selection\';\n    $(\'#start-up\').disabled = !picked.length;\n  };\n  $(\'#pick\').onclick = e => { e.preventDefault(); $(\'#files\').click(); };\n  $(\'#files\').onchange = e => setFiles(e.target.files);\n  const drop = $(\'#drop\');\n  drop.ondragover = e => { e.preventDefault(); drop.classList.add(\'over\'); };\n  drop.ondragleave = () => drop.classList.remove(\'over\');\n  drop.ondrop = e => { e.preventDefault(); drop.classList.remove(\'over\'); setFiles(e.dataTransfer.files); };\n\n  $(\'#start-up\').onclick = async () => {\n    const btn = $(\'#start-up\'), msg = $(\'#up-msg\'), bar = $(\'#up-progress\');\n    btn.disabled = true; bar.classList.remove(\'hidden\');\n    try {\n      const job = await api(\'/api/jobs\', { method: \'POST\', body: JSON.stringify({\n        source: \'upload\', name: $(\'#up-name\').value, per_set: +$(\'#up-per-set\').value }) });\n      const total = picked.reduce((a, f) => a + f.size, 0); let sent = 0;\n      for (let i = 0; i < picked.length; i++) {\n        const fd = new FormData(); fd.append(\'files\', picked[i]);\n        msg.textContent = `Uploading ${i + 1} of ${picked.length}…`;\n        const r = await fetch(`/api/jobs/${job.id}/upload`, { method: \'POST\', body: fd });\n        if (!r.ok) throw new Error(`Upload failed on ${picked[i].name}`);\n        sent += picked[i].size; $(\'div\', bar).style.width = `${100 * sent / total}%`;\n      }\n      await api(`/api/jobs/${job.id}/start`, { method: \'POST\' });\n      msg.textContent = \'Uploaded. Editing has started.\'; picked = [];\n      location.hash = `#/job/${job.id}`;\n    } catch (e) { msg.className = \'msg err\'; msg.textContent = e.message; btn.disabled = false; }\n    bar.classList.add(\'hidden\'); $(\'div\', bar).style.width = \'0\';\n  };\n\n  // ------------------------------------------------------------ job page\n  let current = null, shown = new Set();\n  function baHTML(jid, name) {\n    const n = encodeURIComponent(name);\n    return `<img class="after" src="/jobs/${jid}/after/${n}.jpg" alt="Edited ${esc(name)}" loading="lazy">\n      <img class="before" src="/jobs/${jid}/before/${n}.jpg" alt="Original ${esc(name)}" loading="lazy">\n      <div class="handle"></div><span class="tag l">Before</span><span class="tag r">After</span>`;\n  }\n  function wireBA(el) {\n    const set = x => {\n      const r = el.getBoundingClientRect();\n      const p = Math.max(0, Math.min(100, 100 * (x - r.left) / r.width));\n      $(\'.before\', el).style.clipPath = `inset(0 ${100 - p}% 0 0)`;\n      $(\'.handle\', el).style.left = `${p}%`;\n    };\n    let down = false;\n    el.addEventListener(\'pointerdown\', e => { if (e.target.closest(\'.zoom\')) return; down = true; el.setPointerCapture(e.pointerId); set(e.clientX); });\n    el.addEventListener(\'pointermove\', e => { if (down) set(e.clientX); });\n    el.addEventListener(\'pointerup\', () => { down = false; });\n  }\n\n  async function loadJob(jid, quiet) {\n    let j;\n    try { j = await api(`/api/jobs/${jid}`); } catch (e) { if (!quiet) location.hash = \'#/\'; return; }\n    if (current !== jid) return;\n    $(\'#job-name\').textContent = j.name;\n    const st = j.status === \'done\' ? `${j.photo_count} photos · from ${j.raw_count} RAWs` :\n      j.status === \'error\' ? `Stopped: ${j.error}` : (j.message || j.status_label);\n    $(\'#job-status\').textContent = st;\n    $(\'#job-status\').className = j.status === \'error\' ? \'error\' : \'muted\';\n    $(\'#job-progress\').classList.toggle(\'hidden\', [\'done\', \'error\'].includes(j.status));\n    $(\'#job-progress div\').style.width = `${pct(j)}%`;\n    $(\'#job-zip\').classList.toggle(\'hidden\', !j.local_count);\n    $(\'#job-zip\').href = `/jobs/${j.id}/download.zip`;\n    $(\'#job-retry\').classList.toggle(\'hidden\', !(j.status === \'error\' || (j.status === \'done\' && j.save_error)));\n    $(\'#job-dest\').textContent = !j.dropbox_dest || !j.save_to_dropbox ? \'\' :\n      j.save_error ? `Could not save to Dropbox, so the photos are kept here (use Download all). Reason: ${j.save_error}` :\n      `${j.saved_count} of ${j.sets_total || j.photo_count} saved to Dropbox: ${j.dropbox_dest}/`;\n    const failed = $(\'#job-failed\');\n    failed.classList.toggle(\'hidden\', !j.failed.length);\n    failed.textContent = j.failed.length ? `Could not edit: ${j.failed.map(f => f.name).join(\', \')}` : \'\';\n    const gal = $(\'#gallery\');\n    for (const p of j.photos) {\n      if (shown.has(p.name)) continue;\n      shown.add(p.name);\n      const card = document.createElement(\'div\');\n      card.className = \'photo\';\n      card.innerHTML = `<div class="ba">${baHTML(j.id, p.name)}<button class="zoom">Enlarge</button></div>\n        <div class="meta"><span class="muted">${esc(p.name)} · ${p.frames.length} bracket${p.frames.length === 1 ? \'\' : \'s\'}</span>\n        ${p.in_dropbox ? \'<span class="muted">In Dropbox</span>\' : `<a href="/jobs/${j.id}/full/${encodeURIComponent(p.name)}.jpg">Download</a>`}</div>`;\n      gal.appendChild(card);\n      wireBA($(\'.ba\', card));\n      $(\'.zoom\', card).onclick = e => { e.stopPropagation(); openViewer(j.id, p.name); };\n    }\n  }\n\n  function openViewer(jid, name) {\n    const v = $(\'#viewer\'), ba = $(\'#viewer-ba\');\n    ba.innerHTML = baHTML(jid, name).replaceAll(\' loading="lazy"\', \'\');\n    const af = $(\'.after\', ba);\n    af.onerror = () => { af.onerror = null; af.src = `/jobs/${jid}/after/${encodeURIComponent(name)}.jpg`; };\n    af.src = `/jobs/${jid}/full/${encodeURIComponent(name)}.jpg`;  // full-size edit (preview if it now lives in Dropbox)\n    $(\'#viewer-cap\').textContent = name;\n    v.classList.remove(\'hidden\'); wireBA(ba);\n  }\n  $(\'.viewer-close\').onclick = () => $(\'#viewer\').classList.add(\'hidden\');\n  document.addEventListener(\'keydown\', e => { if (e.key === \'Escape\') $(\'#viewer\').classList.add(\'hidden\'); });\n\n  $(\'#job-retry\').onclick = async () => { await api(`/api/jobs/${current}/retry`, { method: \'POST\' }); loadJob(current); };\n  let deleteArmed = false;\n  $(\'#job-delete\').onclick = async () => {\n    const b = $(\'#job-delete\');\n    if (!deleteArmed) { deleteArmed = true; b.textContent = \'Click again to delete\'; setTimeout(() => { deleteArmed = false; b.textContent = \'Delete\'; }, 4000); return; }\n    try { await api(`/api/jobs/${current}`, { method: \'DELETE\' }); location.hash = \'#/\'; refresh(); }\n    catch (e) { b.textContent = e.message; }\n  };\n\n  // ------------------------------------------------------------ routing\n  function route() {\n    const m = location.hash.match(/^#\\/job\\/([\\w-]+)/);\n    $(\'#viewer\').classList.add(\'hidden\');\n    if (m) {\n      if (current !== m[1]) { current = m[1]; shown = new Set(); $(\'#gallery\').innerHTML = \'\'; }\n      $(\'#home\').classList.add(\'hidden\'); $(\'#job\').classList.remove(\'hidden\');\n      loadJob(current);\n    } else {\n      current = null;\n      $(\'#job\').classList.add(\'hidden\'); $(\'#home\').classList.remove(\'hidden\');\n    }\n    window.scrollTo(0, 0);\n  }\n  window.addEventListener(\'hashchange\', route);\n  if (/dropbox=connected/.test(location.search)) history.replaceState(null, \'\', \'/\');\n  route(); refresh(); setInterval(refresh, 4000);\n})();\n'

INDEX_HTML = '<!doctype html>\n<html lang="en">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width, initial-scale=1">\n<title>HSH Studio · HDR editor</title>\n<link rel="stylesheet" href="/static/style.css">\n</head>\n<body>\n<header class="topbar">\n  <a class="brand" href="#/"><span class="mark">HSH</span><span class="brand-sub">Studio</span></a>\n  <div class="top-right">\n    <span id="dbx-pill" class="pill">Dropbox…</span>\n    <a class="link" href="/logout">Sign out</a>\n  </div>\n</header>\n\n<main id="home">\n  <section class="card new-edit">\n    <div class="card-head">\n      <h1>New edit</h1>\n      <div class="tabs" role="tablist">\n        <button class="tab active" data-tab="dropbox" role="tab">Dropbox link</button>\n        <button class="tab" data-tab="upload" role="tab">Upload RAWs</button>\n      </div>\n    </div>\n\n    <div class="tab-body" data-body="dropbox">\n      <label for="link">Dropbox folder with the RAW brackets</label>\n      <input id="link" type="url" placeholder="https://www.dropbox.com/scl/fo/…" autocomplete="off">\n      <div class="row">\n        <div class="grow">\n          <label for="name">Property name <span class="muted">(optional)</span></label>\n          <input id="name" type="text" placeholder="e.g. 1214 Wilder St">\n        </div>\n        <div>\n          <label for="per-set">Brackets per photo</label>\n          <select id="per-set"><option value="0">Auto-detect</option><option value="3">3</option><option value="5">5</option><option value="7">7</option></select>\n        </div>\n      </div>\n      <label class="check"><input id="save-dbx" type="checkbox" checked> Save the edited photos to an <b>edited</b> folder next to the RAWs</label>\n      <div class="actions"><button id="start-dbx" class="btn primary">Start editing</button><span id="dbx-msg" class="msg"></span></div>\n    </div>\n\n    <div class="tab-body hidden" data-body="upload">\n      <div id="drop" class="drop">\n        <input id="files" type="file" multiple hidden>\n        <p><b>Drop RAW files here</b> or <button class="btn small" id="pick">choose files</button></p>\n        <p class="muted">All brackets for the property · RW2, CR3, CR2, NEF, ARW, DNG…</p>\n      </div>\n      <div class="row">\n        <div class="grow">\n          <label for="up-name">Property name</label>\n          <input id="up-name" type="text" placeholder="e.g. 1214 Wilder St">\n        </div>\n        <div>\n          <label for="up-per-set">Brackets per photo</label>\n          <select id="up-per-set"><option value="0">Auto-detect</option><option value="3">3</option><option value="5">5</option><option value="7">7</option></select>\n        </div>\n      </div>\n      <div id="up-progress" class="progress hidden"><div></div></div>\n      <div class="actions"><button id="start-up" class="btn primary" disabled>Upload &amp; edit</button><span id="up-msg" class="msg"></span></div>\n    </div>\n  </section>\n\n  <section>\n    <h2 class="section-title">Recent edits</h2>\n    <div id="jobs" class="jobs"><p class="muted">Loading…</p></div>\n  </section>\n</main>\n\n<main id="job" class="hidden">\n  <div class="job-head">\n    <a class="link" href="#/">← All edits</a>\n    <div class="job-title">\n      <h1 id="job-name"></h1>\n      <p id="job-status" class="muted"></p>\n    </div>\n    <div class="job-actions">\n      <button id="job-retry" class="btn hidden">Try again</button>\n      <a id="job-zip" class="btn primary hidden" href="#">Download all</a>\n      <button id="job-delete" class="btn ghost">Delete</button>\n    </div>\n  </div>\n  <div id="job-progress" class="progress"><div></div></div>\n  <p id="job-dest" class="muted"></p>\n  <div id="job-failed" class="notice hidden"></div>\n  <div id="gallery" class="gallery"></div>\n</main>\n\n<div id="viewer" class="viewer hidden" role="dialog" aria-modal="true">\n  <button class="viewer-close" aria-label="Close">×</button>\n  <div class="ba big-ba" id="viewer-ba"></div>\n  <p class="viewer-cap" id="viewer-cap"></p>\n</div>\n\n<script src="/static/app.js"></script>\n</body>\n</html>\n'

